// DeleteUniqueIndexCache 删除索引存在的缓存
func (u *UserMembershipChangeRepo) DeleteIndexCache(ctx context.Context, data ...*ai_boilerplate_model.UserMembershipChange) error {
	KeyMap := make(map[string]struct{})
	keys := make([]string, 0)
	keys = append(keys, u.cache.Key(CacheUserMembershipChangeByConditionPrefix))
	keys = append(keys, u.cache.Key(CacheUserMembershipChangeUnscopedByConditionPrefix))
	for _, item := range data {
		if item != nil {
			KeyMap[u.cache.Key(CacheUserMembershipChangeByIDPrefix, item.ID)] = struct{}{}
			KeyMap[u.cache.Key(CacheUserMembershipChangeUnscopedByIDPrefix, item.ID)] = struct{}{}
			KeyMap[u.cache.Key(CacheUserMembershipChangeBySourceTypePrefix, item.SourceType)] = struct{}{}
			KeyMap[u.cache.Key(CacheUserMembershipChangeUnscopedBySourceTypePrefix, item.SourceType)] = struct{}{}
			KeyMap[u.cache.Key(CacheUserMembershipChangeByUserIDCreatedAtPrefix, item.UserID, item.CreatedAt)] = struct{}{}
			KeyMap[u.cache.Key(CacheUserMembershipChangeUnscopedByUserIDCreatedAtPrefix, item.UserID, item.CreatedAt)] = struct{}{}
			KeyMap[u.cache.Key(CacheUserMembershipChangeByUserIDPrefix, item.UserID)] = struct{}{}
			KeyMap[u.cache.Key(CacheUserMembershipChangeUnscopedByUserIDPrefix, item.UserID)] = struct{}{}
		}
	}
	for item := range KeyMap {
		keys = append(keys, item)
	}
	err := u.cache.DelBatch(ctx, keys)
	if err != nil {
		return err
	}
	return nil
}
